/* @autogenerated */
package net.civeira.phylax.integrationtest.features.oauth.scenario;

import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.function.BiFunction;

import jakarta.annotation.Priority;
import jakarta.enterprise.context.ApplicationScoped;
import jakarta.enterprise.inject.Alternative;
import net.civeira.phylax.features.oauth.authentication.domain.AuthenticationChallege;
import net.civeira.phylax.features.oauth.consent.domain.ScopePermission;
import net.civeira.phylax.features.oauth.consent.domain.gateway.ScopeApprovalGateway;
import net.civeira.phylax.features.oauth.consent.domain.gateway.ScopesConsentGateway;

@Alternative
@Priority(1)
@ApplicationScoped
public class ScenarioScopeConsentGateway implements ScopesConsentGateway, ScopeApprovalGateway {

  /**
   * Default behavior: returns all requested scopes as pending (none pre-authorized).
   */
  private BiFunction<String, List<String>, List<String>> pendingProvider =
      (_, requested) -> new ArrayList<>(requested);

  private final AtomicInteger acceptedCount = new AtomicInteger();
  private String lastTenant;
  private String lastUsername;
  private String lastClientId;
  private List<String> lastAcceptedScopes;

  public void whenPending(BiFunction<String, List<String>, List<String>> behavior) {
    this.pendingProvider = behavior;
  }

  /** Simulates all scopes already authorized (nothing pending). */
  public void whenNoPending() {
    this.pendingProvider = (_, _) -> List.of();
  }

  public void reset() {
    pendingProvider = (_, requested) -> new ArrayList<>(requested);
    acceptedCount.set(0);
    lastTenant = null;
    lastUsername = null;
    lastClientId = null;
    lastAcceptedScopes = null;
  }

  public int getAcceptedCount() {
    return acceptedCount.get();
  }

  public String getLastTenant() {
    return lastTenant;
  }

  public String getLastUsername() {
    return lastUsername;
  }

  public String getLastClientId() {
    return lastClientId;
  }

  public List<String> getLastAcceptedScopes() {
    return lastAcceptedScopes;
  }

  @Override
  public List<ScopePermission> pendingScopes(String tenant, String username, String clientId,
      List<String> requestedScopes) {
    return buildPermissions(clientId, requestedScopes);
  }

  @Override
  public void storeAcceptedScopes(String tenant, String username, String clientId,
      List<String> scopes) {
    recordAccepted(tenant, username, clientId, scopes);
  }

  @Override
  public List<ScopePermission> pendingApprovals(String tenant, String username, String clientId,
      List<String> requestedScopes, List<AuthenticationChallege> completedChallenges) {
    return buildPermissions(clientId, requestedScopes);
  }

  @Override
  public void storeApprovedScopes(String tenant, String username, String clientId,
      List<String> acceptedScopes) {
    recordAccepted(tenant, username, clientId, acceptedScopes);
  }

  private List<ScopePermission> buildPermissions(String clientId, List<String> requestedScopes) {
    return pendingProvider.apply(clientId, requestedScopes).stream()
        .map(s -> ScopePermission.builder().scope(s).required(true).build()).toList();
  }

  private void recordAccepted(String tenant, String username, String clientId,
      List<String> scopes) {
    acceptedCount.incrementAndGet();
    lastTenant = tenant;
    lastUsername = username;
    lastClientId = clientId;
    lastAcceptedScopes = scopes;
  }
}
